Algorithm OneToTen
  Define n As Integer;
  Repeat
    Read n;
  Until n >= 1 And n <= 10
  Write "Accepted: ", n;
EndAlgorithm

Algorithm Highest
  Define temperature As Integer;
  Define highest As Integer;
  Read highest;
  For i <- 2 To 5 Do
    Read temperature;
    If temperature > highest Then
      highest <- temperature;
    EndIf
  EndFor
  Write "Highest: ", highest;
EndAlgorithm

Algorithm Prime
  Define n As Integer;
  Read n;
  Define isPrime As Boolean <- n >= 2;
  For d <- 2 To n - 1 Do
    If n Mod d = 0 Then
      isPrime <- False;
      Break;
    EndIf
  EndFor
  If isPrime Then
    Write "Is prime";
  Else
    Write "Not prime";
  EndIf
EndAlgorithm
